import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    count = 0
    for i in range(n):
        for j in range(i, n):
            if sum(a[i:j + 1]) <= s:
                count += 1
    print(count)


